void * HkSession_ctor(void * instance, void * sessionCinfo) __asm__("\"??0HkSession$$QEAA$AEBUHkSessionCinfo$0$$Z\"");
void * HkSession_ctor(void * instance, void * sessionCinfo)
{
    ensure_thread_info();
    alignas(void *) uint8_t cinfo[96];
    std::memcpy(cinfo, sessionCinfo, sizeof(cinfo));
    void *callback = *reinterpret_cast<void **>(cinfo);
    if (callback)
        *reinterpret_cast<void **>(cinfo) = reinterpret_cast<void *>(&contact_impulse_bridge);
    sessionCinfo = cinfo;
    void *result = pHkSession_ctor(instance, sessionCinfo);
    if (result && callback) {
        std::lock_guard<std::mutex> lock(contact_mutex);
        contact_callbacks[result] = reinterpret_cast<ContactImpulseCallback>(callback);
    }
    return result;
}

void HkSession_dtor(void * instance) __asm__("\"??1HkSession$$QEAA$XZ\"");
void HkSession_dtor(void * instance)
{
    ensure_thread_info();
    {
        std::lock_guard<std::mutex> lock(contact_mutex);
        for (auto route = contact_routes.begin(); route != contact_routes.end();) {
            if (route->second.session == instance)
                route = contact_routes.erase(route);
            else
                ++route;
        }
        contact_callbacks.erase(instance);
    }
    pHkSession_dtor(instance);
}

